// 重分类函数
function reclassify(image, rules) {
  var classified = ee.Image(0);
  for (var i = 0; i < rules.length; i++) {
    var rule = rules[i];
    classified = classified.where(
      image.gte(rule[0]).and(image.lt(rule[1])), 
      rule[2]
    );
  }
  return classified;
}

