// 计算火灾后 NBR
var nbr_post = lc08_post_d.normalizedDifference(['B5', 'B6']);

// 计算燃烧严重性指数 (CSI) = NBR_pre - NBR_post
var csi = nbr_pre.subtract(nbr_post);

